W("Where did the Martian space crew land on Earth?", 1, "(c) In the Centerville Public Library", "E", opts=["In a school", "In a museum", "In the Centerville Public Library", "In a bookshop in London"]),
W("Why was the twentieth century called the 'Era of the Book'?", 2, "Because in those days there were books about everything, from ant eaters to Zulus; books taught, illustrated, educated, punctuated and even decorated. (2)", "E"),
