 ("table", ["Point", "Detail"], [["Genre", "Science-fiction comedy / one-act play"], ["Time", "The twenty-fifth century (frame); the invasion year is 2040"], ["Place", "Museum of Ancient History; Mars Space Control; Centerville Public Library"], ["Technique", "A play within a play, introduced by the Historian's 'historiscope'"], ["Theme", "Misunderstanding, pride, the power of books"]]),
